// ============================================================================
// STAGE 1 FILTER: HYGIENE, SPAM, AUTO-REPLY & SHA-256 DEDUPLICATION
// ============================================================================
const crypto = require('crypto');

const items = $input.all();
const output = [];

const hardDropSenders = /(no-reply|noreply|donotreply|do-not-reply|mailer-daemon|postmaster|marketing|newsletter|sales@)/i;
const autoReplySubjects = /(out\s+of\s+office|auto-reply|automatic\s+reply|undelivered\s+mail|delivery\s+status\s+notification)/i;

for (const item of items) {
  const json = item.json || {};
  const sender = (json.from || json.sender || "").toLowerCase();
  const subject = (json.subject || "").toLowerCase();

  // 1. Drop obvious spam/marketing
  if (hardDropSenders.test(sender)) {
    item.json.dropReason = "SPAM_MARKETING_SENDER";
    item.json.pipelineStatus = "SPAM_DROPPED";
    continue;
  }

  // 2. Reroute auto-replies unless an attachment is present
  const hasAttachments = Boolean(item.binary && Object.keys(item.binary).length > 0);
  if (autoReplySubjects.test(subject) && !hasAttachments) {
    item.json.dropReason = "AUTO_REPLY_NO_ATTACHMENT";
    item.json.pipelineStatus = "AUTO_REPLY_LOGGED";
    continue;
  }

  // 3. Compute SHA-256 Hashes for duplicate detection
  const hashes = [];
  if (hasAttachments) {
    for (const key of Object.keys(item.binary)) {
      const base64Data = item.binary[key].data || "";
      const hash = crypto.createHash('sha256').update(base64Data).digest('hex');
      hashes.push(hash);
    }
  }
  item.json.attachmentHashes = hashes;
  item.json.stage1Passed = true;
  output.push(item);
}

return output;

// ============================================================================
// STAGE 2 FILTER: QUALIFICATION, ROUTING & SIZE CHECK
// ============================================================================
const items = $input.all();
const output = [];

const coreKeywords = /\b(invoice|invoices|invoicing|billable|billed|remittance|remit|voucher|statement|surcharge|demurrage|detention|drayage|lumper|accessorial|ratecon|manifest|waybill|freight)\b/i;
const shorthandPatterns = /\b(inv|bill|bol|pod|po|so|awb|cmr)[\s:#\-_0-9]/i;

const MAX_FILE_SIZE_BYTES = 15 * 1024 * 1024; // 15MB threshold

for (const item of items) {
  const json = item.json || {};
  const subject = (json.subject || "").toLowerCase();
  const body = (json.textPlain || json.text || json.snippet || "").toLowerCase();
  const hasAttachments = Boolean(item.binary && Object.keys(item.binary).length > 0);

  let isOverSize = false;
  if (hasAttachments) {
    for (const key of Object.keys(item.binary)) {
      const size = item.binary[key].fileSize || 0;
      if (size > MAX_FILE_SIZE_BYTES) {
        isOverSize = true;
        break;
      }
    }
  }

  if (isOverSize) {
    item.json.routeGroup = "LARGE_FILE_TRIAGE";
    item.json.confidenceTag = "EXCEEDS_MAX_SIZE";
    output.push(item);
    continue;
  }

  const hasKeywords = coreKeywords.test(subject) || 
                      coreKeywords.test(body) || 
                      shorthandPatterns.test(subject) || 
                      shorthandPatterns.test(body);

  if (hasAttachments) {
    item.json.routeGroup = "ATTACHMENT_PIPELINE";
    item.json.confidenceTag = hasKeywords ? "HIGH_SIGNAL_ATTACHMENT" : "UNLABELED_ATTACHMENT";
    output.push(item);
  } else {
    if (hasKeywords) {
      item.json.routeGroup = "AI_BODY_PIPELINE";
      item.json.confidenceTag = "HIGH_SIGNAL_TEXT";
      output.push(item);
    } else {
      item.json.routeGroup = "JEV_FAST_CLASSIFIER";
      item.json.confidenceTag = "AMBIGUOUS_TEXT";
      output.push(item);
    }
  }
}

return output;

