// ============================================================================
// JEV EVALUATOR & FALLBACK HANDLER
// ============================================================================
const items = $input.all();
const output = [];

for (const item of items) {
  if (item.json.error) {
    item.json.routeGroup = "AI_BODY_PIPELINE";
    item.json.jevStatus = "JEV_TIMEOUT_FALLBACK";
    output.push(item);
    continue;
  }

  const classification = (item.json.result || item.json.classification || "").toString().toUpperCase();
  if (classification.includes("YES")) {
    item.json.routeGroup = "AI_BODY_PIPELINE";
    item.json.jevStatus = "CLASSIFIED_YES";
    output.push(item);
  } else {
    item.json.routeGroup = "HUMAN_TRIAGE";
    item.json.jevStatus = "CLASSIFIED_NO";
    item.json.dbStatus = "HUMAN_TRIAGE_QUEUE";
    output.push(item);
  }
}

return output;

// ============================================================================
// NORMALIZER & SCHEMA VALIDATOR
// ============================================================================
const items = $input.all();
const output = [];

for (const item of items) {
  let rawContent = item.json.message?.content || item.json.content || item.json.text || item.json.output || "";

  if (typeof rawContent === 'object') {
    rawContent = JSON.stringify(rawContent);
  }

  // Strip Markdown Code Fences (e.g. ```json ... ```)
  if (typeof rawContent === 'string') {
    rawContent = rawContent.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
  }

  let parsedData = {};
  try {
    parsedData = JSON.parse(rawContent);
  } catch (e) {
    parsedData = {};
  }

  const requiredFields = ['vendor_name', 'total_amount'];
  const hasRequiredFields = requiredFields.every(field => Boolean(parsedData[field]));

  if (!hasRequiredFields) {
    item.json.validationStatus = "SCHEMA_VALIDATION_FAILED";
    item.json.dbStatus = "FAILED_DLQ_TRIAGE";
  } else {
    item.json.validationStatus = "VALIDATED";
    item.json.dbStatus = "PENDING_HUMAN_REVIEW";
  }

  item.json.normalizedPayload = parsedData;
  output.push(item);
}

return output;
